<?php
declare(strict_types=1);
require dirname(__DIR__, 2) . '/UE4/UnrealPackageReader.php';
require dirname(__DIR__) . '/src/Infrastructure/Readers/CatalogReaderResolver.php';

$resolvedReader = \UnrealDb\Catalog\Infrastructure\Readers\CatalogReaderResolver::resolve(
    ['engine_readers' => ['UE4' => ['reader' => 'UE4CatalogReader.php', 'class' => 'UnrealPackageReader4']]],
    'UE4', 'Reader missing:', 'Reader class missing:', ['UE4']
);

// Native fixtures MUST be generated by UE427Oracle's FPackageFileSummary writer,
// never reinterpreted from UnrealDB's serializer.
$directory = rtrim($argv[1] ?? 'C:/Temp/ue427-native-fixtures', '/\\');
$defaultLog = $argv[2] ?? 'C:/Temp/ue427-native-fixtures-default.log';
$allowedLog = $argv[3] ?? 'C:/Temp/ue427-native-fixtures-allowed.log';

function nativeDiagnostics(string $path): array
{
    $raw = @file_get_contents($path);
    if (!is_string($raw)) throw new RuntimeException('Missing Epic-native oracle log: ' . $path);
    if (str_starts_with($raw, "\xFF\xFE")) {
        $raw = mb_convert_encoding(substr($raw, 2), 'UTF-8', 'UTF-16LE');
    }
    $records = [];
    foreach (explode("\n", $raw) as $line) {
        $prefix = 'UE427_NATIVE_DIAGNOSTIC|';
        $start = strpos($line, $prefix);
        if ($start === false) continue;
        $parts = explode('|', trim(substr($line, $start + strlen($prefix))));
        if (count($parts) !== 7) throw new RuntimeException('Malformed Epic-native diagnostic row');
        $name = array_shift($parts);
        $records[$name] = array_combine(
            ['version', 'unversioned', 'byteSwapping', 'archiveError', 'endOffset', 'totalHeaderSize'],
            array_map('intval', $parts)
        );
    }
    return $records;
}

$defaultNative = nativeDiagnostics($defaultLog);
$allowedNative = nativeDiagnostics($allowedLog);
$cases = [];
foreach ([
    'native-little.uasset' => [false, false],
    'native-swapped.uasset' => [true, false],
    'native-unversioned.uasset' => [false, true],
] as $name => [$swapped, $unversioned]) {
    $path = $directory . '/' . $name;
    if (!is_file($path) || filesize($path) !== 4096) {
        throw new RuntimeException('Missing/malformed native fixture: ' . $path);
    }
    $bytes = file_get_contents($path, false, null, 0, 4);
    $expectedTag = pack($swapped ? 'N' : 'V', 0x9E2A83C1);
    $default = new $resolvedReader($path);
    $permitted = new $resolvedReader($path, ['allow_unversioned_content_in_editor' => true]);
    $defaultHeader = $default->getHeader();
    $permittedHeader = $permitted->getHeader();
    $epicDefault = $defaultNative[$name] ?? [];
    $epicPermitted = $allowedNative[$name] ?? [];
    $defaultPass = $default->validatePackage() === [];
    $permittedPass = $permitted->validatePackage() === [];
    $expectedDefaultVersion = $unversioned ? 0 : 522;
    $expectedDefaultHeader = $unversioned ? 0 : 4096;
    $checks = [
        'production_resolver_selects_ue4' => $resolvedReader === 'UnrealPackageReader4',
        'native_serialized_tag' => $bytes === $expectedTag,
        'default_acceptance' => $defaultPass === !$unversioned,
        'allowed_acceptance' => $permittedPass,
        'native_default_version' => ($epicDefault['version'] ?? -1) === $expectedDefaultVersion,
        'native_allowed_version' => ($epicPermitted['version'] ?? -1) === 522,
        'native_default_header' => ($epicDefault['totalHeaderSize'] ?? -1) === $expectedDefaultHeader,
        'native_allowed_header' => ($epicPermitted['totalHeaderSize'] ?? -1) === 4096,
        'native_archive_no_errors' => ($epicDefault['archiveError'] ?? -1) === 0 && ($epicPermitted['archiveError'] ?? -1) === 0,
        'native_swapping' => ($epicDefault['byteSwapping'] ?? -1) === (int)$swapped && ($epicPermitted['byteSwapping'] ?? -1) === (int)$swapped,
        'native_unversioned_policy' => ($epicDefault['unversioned'] ?? -1) === 0 && ($epicPermitted['unversioned'] ?? -1) === (int)$unversioned,
        'reader_swapping' => (bool)($permittedHeader['byteSwapping'] ?? null) === $swapped,
        'reader_version' => (int)($permittedHeader['version'] ?? -1) === 522,
        'reader_unversioned_state' => (bool)($permittedHeader['unversioned'] ?? null) === $unversioned,
        'reader_summary_size' => (int)($permittedHeader['totalHeaderSize'] ?? -1) === 4096,
    ];
    $cases[$name] = ['ok' => !in_array(false, $checks, true), 'checks' => $checks,
        'epic_default' => $epicDefault, 'epic_permitted' => $epicPermitted,
        'reader_default_errors' => $default->validatePackage(),
        'reader_allowed_errors' => $permitted->validatePackage()];
}
$ok = !in_array(false, array_column($cases, 'ok'), true);
echo json_encode(['ok' => $ok, 'fixture_count' => count($cases),
    'assertion_count' => count($cases) * 15, 'cases' => $cases], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES), PHP_EOL;
exit($ok ? 0 : 2);
